style.css:
@-moz-document domain("youtube.com") {
/*=========================
  Colors
=========================*/

:root{

    --ocean:#9EEBFF;
    --ocean-light:#D8F8FF;
    --ocean-mid:#8FE7FF;
    --ocean-dark:#63CFF7;

    --glass:rgba(20,55,80,.72);

}

/*=========================
  Background
=========================*/

html,
body,
ytd-app{

    background:
        linear-gradient(
            rgba(12,40,65,.50),
            rgba(12,40,65,.50)
        ),
        url("https://i.pinimg.com/1200x/61/3f/0b/613f0b9401698d8aa6be9fdd86ff27c1.jpg")
        center center / cover fixed !important;

}

/*=========================
  Header
=========================*/

#masthead-container{

    background:rgba(18,55,80,.80)!important;

    backdrop-filter:blur(18px);

    border-bottom:1px solid rgba(158,235,255,.30);

}

/*=========================
  Sidebar
=========================*/

#guide-content,
tp-yt-app-drawer{

    background:rgba(18,55,80,.78)!important;

    backdrop-filter:blur(16px);

}

/*=========================
  Main
=========================*/

#page-manager,
#primary,
#secondary,
ytd-browse{

    background:transparent!important;

}

/*=========================
  Video Cards
=========================*/

ytd-rich-item-renderer,
ytd-video-renderer,
ytd-grid-video-renderer,
ytd-compact-video-renderer{

    background:rgba(255,255,255,.08)!important;

    backdrop-filter:blur(12px);

    border-radius:18px;

    transition:.25s;

}

ytd-rich-item-renderer:hover,
ytd-video-renderer:hover{

    transform:translateY(-3px);

    box-shadow:
        0 0 15px rgba(158,235,255,.45);

}

/*=========================
  Search Bar
=========================*/

input,
#search{

    background:rgba(255,255,255,.08)!important;

    color:white!important;

    border-radius:30px!important;

}

/*=========================
  Buttons
=========================*/

button,
yt-icon-button{

    border-radius:20px!important;

}

button:hover,
yt-icon-button:hover{

    background:rgba(158,235,255,.18)!important;

}

/*=========================
  Subscribe Button
=========================*/

ytd-subscribe-button-renderer button{

    background:
        linear-gradient(
            135deg,
            var(--ocean-light),
            var(--ocean),
            var(--ocean-dark)
        )!important;

    color:#15435d!important;

    border:none!important;

}

/*=========================
  Links
=========================*/

a{

    color:var(--ocean)!important;

}

a:hover{

    color:var(--ocean-light)!important;

}

/*=========================
  Text
=========================*/

yt-formatted-string,
#video-title,
#text,
h1,
h2,
h3{

    color:#F5FDFF!important;

}

/*=========================
  Animated Ocean Progress Bar
=========================*/

.ytp-play-progress{

    position:relative;

    overflow:hidden;

    background:
        linear-gradient(
            90deg,
            #D8F8FF,
            #BFF5FF,
            #8FE7FF,
            #63CFF7,
            #8FE7FF,
            #D8F8FF
        )!important;

    background-size:300% 100%;

    animation:OceanFlow 3s linear infinite;

    box-shadow:
        0 0 8px rgba(180,240,255,.8),
        0 0 18px rgba(120,220,255,.55);

}

/* Moving wave shine */

.ytp-play-progress::after{

    content:"";

    position:absolute;

    inset:0;

    background:
        linear-gradient(
            120deg,
            transparent 15%,
            rgba(255,255,255,.45) 50%,
            transparent 85%
        );

    background-size:200% 100%;

    animation:WaveShine 2.5s linear infinite;

}

.ytp-load-progress{

    background:rgba(255,255,255,.28)!important;

}

/*=========================
  Video Player
=========================*/

.html5-video-player{

    border-radius:18px;

    overflow:hidden;

}

/*=========================
  Scrollbar
=========================*/

::-webkit-scrollbar{

    width:10px;

}

::-webkit-scrollbar-track{

    background:#21435d;

}

::-webkit-scrollbar-thumb{

    background:
        linear-gradient(
            #D8F8FF,
            #9EEBFF,
            #63CFF7
        );

    border-radius:20px;

}

/*=========================
  Selection
=========================*/

::selection{

    background:#9EEBFF;

    color:#08334d;

}

/*=========================
  Animations
=========================*/

@keyframes OceanFlow{

    0%{
        background-position:0% 50%;
    }

    100%{
        background-position:300% 50%;
    }

}

@keyframes WaveShine{

    from{
        background-position:200% 0;
    }

    to{
        background-position:-100% 0;
    }

}
}
